package local.skyfamily;
import android.graphics.*;import android.view.*;import android.widget.*;import android.os.Handler;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.json.JSONObject;
final class PdfPane extends LinearLayout {
 final PolishActivity host;final JSONObject book;final File file;final String key;final Handler ui=new Handler();final ExecutorService jobs=Executors.newSingleThreadExecutor();TextView status;ZoomPage image;int page,count=0,generation=0;volatile boolean closed=false;
 PdfPane(PolishActivity h,JSONObject b){super(h);host=h;book=b;file=new File(h.bookDir(),b.optString("file"));key="book."+b.optString("id");page=h.prefs.getInt(key+".pdf.page",0);setOrientation(1);setBackgroundColor(0xff0c1020);LinearLayout top=new LinearLayout(h);addView(top,new LinearLayout.LayoutParams(-1,h.dp(54)));action(top,"Library",()->h.bookshelf());action(top,"Page",()->jump());action(top,"Bookmark",()->bookmark());action(top,"Saved",()->saved());action(top,"Rotate",()->h.screenRotation());image=new ZoomPage();addView(image,new LinearLayout.LayoutParams(-1,0,1));status=new TextView(h);status.setTextColor(h.accent);status.setGravity(Gravity.CENTER);status.setPadding(0,h.dp(8),0,h.dp(8));addView(status);LinearLayout bottom=new LinearLayout(h);addView(bottom,new LinearLayout.LayoutParams(-1,h.dp(54)));action(bottom,"Previous",()->move(-1));action(bottom,"Fit page",()->{image.zoom=1;image.panX=image.panY=0;image.invalidate();});action(bottom,"Next",()->move(1));render();}
 void action(LinearLayout row,String name,Runnable r){TextView t=new TextView(host);t.setText(name);t.setTextColor(host.fg);t.setGravity(Gravity.CENTER);t.setTextSize(14);row.addView(t,new LinearLayout.LayoutParams(0,-1,1));t.setOnClickListener(v->r.run());}
 void render(){final int stamp=++generation,index=page;status.setText("Rendering PDF page...");jobs.submit(()->{if(closed||stamp!=generation)return;try{PdfPages.Page result=PdfPages.render(host,file,index,1200,1600);ui.post(()->{if(closed||stamp!=generation){result.image.recycle();return;}count=result.count;page=Math.max(0,Math.min(count-1,index));image.set(result.image);int percent=(page+1)*100/count;String label="Page "+(page+1)+" / "+count+"   |   "+percent+"%";status.setText(label+"   |   Pinch to zoom / drag to pan");host.prefs.edit().putInt(key+".pdf.page",page).putInt(key+".percent",percent).putString(key+".label",label).putLong(key+".last",System.currentTimeMillis()).putString("books.last",book.optString("id")).apply();});}catch(Exception e){ui.post(()->{if(!closed&&stamp==generation)status.setText("PDF unavailable: "+e.getMessage());});}catch(OutOfMemoryError e){ui.post(()->{if(!closed)status.setText("Not enough memory to render this PDF page");});}});}
 void move(int d){if(closed||count==0)return;page=Math.max(0,Math.min(count-1,page+d));render();}
 void jump(){if(count==0)return;EditText value=new EditText(host);value.setInputType(2);value.setHint("Page 1-"+count);new android.app.AlertDialog.Builder(host).setTitle("Go to page").setView(value).setPositiveButton("Go",(dialog,which)->{try{int n=Integer.parseInt(value.getText().toString());if(n<1||n>count)throw new Exception();page=n-1;render();}catch(Exception e){host.toast("Enter a valid page number");}}).setNegativeButton("Cancel",null).show();}
 Set<String> marks(){return new HashSet<>(host.prefs.getStringSet(key+".marks",new HashSet<>()));}
 void bookmark(){if(count==0)return;Set<String> list=marks();String entry=String.valueOf(page);if(!list.add(entry)){list.remove(entry);host.toast("Bookmark removed");}else host.toast("Page bookmarked");host.prefs.edit().putStringSet(key+".marks",list).apply();}
 void saved(){ArrayList<Integer> pages=new ArrayList<>();for(String s:marks())try{pages.add(Integer.parseInt(s));}catch(Exception ignored){}Collections.sort(pages);if(pages.isEmpty()){host.toast("No bookmarks yet");return;}String[] labels=new String[pages.size()];for(int i=0;i<labels.length;i++)labels[i]="Page "+(pages.get(i)+1);new android.app.AlertDialog.Builder(host).setTitle("Bookmarks").setItems(labels,(dialog,which)->{page=pages.get(which);render();}).show();}
 void close(){if(closed)return;closed=true;generation++;jobs.shutdownNow();ui.removeCallbacksAndMessages(null);image.set(null);}
 protected void onDetachedFromWindow(){close();super.onDetachedFromWindow();}
 class ZoomPage extends View {Bitmap bitmap;Paint pen=new Paint(3);float zoom=1,panX=0,panY=0,lastX,lastY,downX,downY;boolean scaled=false;ScaleGestureDetector scale;ZoomPage(){super(host);scale=new ScaleGestureDetector(host,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector detector){zoom=Math.max(1,Math.min(4,zoom*detector.getScaleFactor()));scaled=true;invalidate();return true;}});}void set(Bitmap b){Bitmap old=bitmap;bitmap=b;zoom=1;panX=panY=0;invalidate();if(old!=null&&old!=b)old.recycle();}protected void onDraw(Canvas canvas){canvas.drawColor(0xff101629);if(bitmap==null)return;float factor=Math.min(getWidth()/(float)bitmap.getWidth(),getHeight()/(float)bitmap.getHeight())*zoom;float w=bitmap.getWidth()*factor,h=bitmap.getHeight()*factor;canvas.drawBitmap(bitmap,null,new RectF((getWidth()-w)/2+panX,(getHeight()-h)/2+panY,(getWidth()+w)/2+panX,(getHeight()+h)/2+panY),pen);}public boolean onTouchEvent(MotionEvent e){scale.onTouchEvent(e);if(e.getAction()==0){lastX=downX=e.getX();lastY=downY=e.getY();scaled=false;}if(e.getAction()==2&&zoom>1&&!scale.isInProgress()){panX+=e.getX()-lastX;panY+=e.getY()-lastY;invalidate();}lastX=e.getX();lastY=e.getY();if(e.getAction()==1&&!scaled&&zoom==1){float delta=e.getX()-downX;if(Math.abs(delta)>host.dp(50))move(delta<0?1:-1);}return true;}}
}
